<section class="card"><h2>Controlled SKU pricing</h2><p>Only independently approved changes become effective. The exact discount per unit is multiplied by quantity on each sale; rejected changes never affect selling.</p></section>
<?php if(!empty($canManagePricing)):?><section class="card"><h3>Request price and exact discount</h3><form method="post" action="<?=e(appBasePath())?>/sales/pricing"><?=csrfField()?><div class="finance-filter-form"><label>SKU<select name="product_id" required><option value="">Select SKU</option><?php foreach($products as $product):?><option value="<?=(int)$product['product_id']?>"><?=e($product['sku'].' — '.$product['name'].' · catalogue '.$product['unit_price'])?></option><?php endforeach;?></select></label><label>Proposed unit price<input name="proposed_price" type="number" min="0.01" step="0.01" required></label><label>Approved discount per unit<input name="approved_discount_per_unit" type="number" min="0" step="0.01" value="0" required></label><label>Effective from<input name="effective_from" type="date" value="<?=e(date('Y-m-d'))?>" required></label><label>Reason<textarea name="reason" maxlength="1000" required></textarea></label></div><button class="btn btn-primary">Submit for approval</button></form></section><?php endif;?>
<section class="card table-card"><h3>Price-change history</h3><div class="table-responsive"><table class="data-table"><thead><tr><th>SKU</th><th>Previous</th><th>Proposed</th><th>Discount/unit</th><th>Currency</th><th>Effective</th><th>Status</th><th>Requester</th><th>Approver</th><th>Reason</th><th>Decision</th></tr></thead><tbody><?php if($rows===[]):?><tr><td colspan="11">No price changes recorded.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td><?=e($row['sku'].' — '.$row['product_name'])?></td><td><?=e($row['old_price'])?></td><td><?=e($row['proposed_price'])?></td><td><?=e($row['approved_discount_per_unit'])?></td><td><?=e($row['currency'])?></td><td><?=e($row['effective_from'])?></td><td><span class="status-badge"><?=e($row['status'])?></span></td><td><?=e($row['requested_by'])?></td><td><?=e($row['approved_by']??'—')?></td><td><?=e($row['reason'])?></td><td><?php if($row['status']==='submitted'&&!empty($canApprovePricing)&&(int)$row['requested_by']!==(int)($_SESSION['auth']['user_id']??0)):?><form method="post" action="<?=e(appBasePath())?>/sales/pricing/<?=(int)$row['price_change_id']?>/decision"><?=csrfField()?><label>Decision reason<input name="reason" maxlength="1000"></label><button class="btn btn-primary" name="decision" value="approve">Approve</button> <button class="btn btn-secondary" name="decision" value="reject">Reject</button></form><?php else:?><?=e($row['decision_reason']??'—')?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
